CREATE TABLE `ActividadKairos` (`id` varchar(30) NOT NULL, `proyectoId` varchar(30) NOT NULL, `responsableId` int NOT NULL, `title` varchar(191) NOT NULL, `description` varchar(3000) NULL, `startAt` datetime(3) NULL, `dueAt` datetime(3) NULL, `closedAt` datetime(3) NULL, `priority` enum('BAJA','MEDIA','ALTA','CRITICA') NOT NULL DEFAULT 'MEDIA', `complexity` enum('BAJA','MEDIA','ALTA') NOT NULL DEFAULT 'MEDIA', `state` enum('PENDIENTE','EN_PROGRESO','BLOQUEADA','EN_REVISION','REQUIERE_CORRECCION','TERMINADA','CANCELADA') NOT NULL DEFAULT 'PENDIENTE', `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` datetime(3) NOT NULL, PRIMARY KEY (`id`), INDEX `ActividadKairos_proyectoId_state_dueAt_idx` (`proyectoId`,`state`,`dueAt`), INDEX `ActividadKairos_responsableId_state_idx` (`responsableId`,`state`), CONSTRAINT `ActividadKairos_proyectoId_fkey` FOREIGN KEY (`proyectoId`) REFERENCES `ProyectoKairos` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `ActividadKairos_responsableId_fkey` FOREIGN KEY (`responsableId`) REFERENCES `Usuario` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ParticipanteActividadKairos` (`actividadId` varchar(30) NOT NULL, `usuarioId` int NOT NULL, `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`actividadId`,`usuarioId`), CONSTRAINT `ParticipanteActividadKairos_actividadId_fkey` FOREIGN KEY (`actividadId`) REFERENCES `ActividadKairos` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `ParticipanteActividadKairos_usuarioId_fkey` FOREIGN KEY (`usuarioId`) REFERENCES `Usuario` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `EntregaEvidenciaKairos` (`id` varchar(30) NOT NULL, `actividadId` varchar(30) NOT NULL, `archivoId` varchar(30) NOT NULL, `authorId` int NOT NULL, `version` int NOT NULL, `comment` varchar(1000) NULL, `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `EntregaEvidenciaKairos_actividadId_version_key` (`actividadId`,`version`), INDEX `EntregaEvidenciaKairos_archivoId_idx` (`archivoId`), CONSTRAINT `EntregaEvidenciaKairos_actividadId_fkey` FOREIGN KEY (`actividadId`) REFERENCES `ActividadKairos` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `EntregaEvidenciaKairos_archivoId_fkey` FOREIGN KEY (`archivoId`) REFERENCES `Archivo` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `EntregaEvidenciaKairos_authorId_fkey` FOREIGN KEY (`authorId`) REFERENCES `Usuario` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ComentarioActividadKairos` (`id` varchar(30) NOT NULL, `actividadId` varchar(30) NOT NULL, `authorId` int NOT NULL, `body` varchar(2000) NOT NULL, `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), INDEX `ComentarioActividadKairos_actividadId_createdAt_idx` (`actividadId`,`createdAt`), CONSTRAINT `ComentarioActividadKairos_actividadId_fkey` FOREIGN KEY (`actividadId`) REFERENCES `ActividadKairos` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `ComentarioActividadKairos_authorId_fkey` FOREIGN KEY (`authorId`) REFERENCES `Usuario` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `HistorialActividadKairos` (`id` varchar(30) NOT NULL, `actividadId` varchar(30) NOT NULL, `actorId` int NOT NULL, `reviewerId` int NULL, `type` enum('TRANSICION','REVISION','REAPERTURA','ENTREGA') NOT NULL, `fromState` enum('PENDIENTE','EN_PROGRESO','BLOQUEADA','EN_REVISION','REQUIERE_CORRECCION','TERMINADA','CANCELADA') NULL, `toState` enum('PENDIENTE','EN_PROGRESO','BLOQUEADA','EN_REVISION','REQUIERE_CORRECCION','TERMINADA','CANCELADA') NULL, `comment` varchar(2000) NULL, `evidenceId` varchar(30) NULL, `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), INDEX `HistorialActividadKairos_actividadId_createdAt_idx` (`actividadId`,`createdAt`), INDEX `HistorialActividadKairos_evidenceId_idx` (`evidenceId`), CONSTRAINT `HistorialActividadKairos_actividadId_fkey` FOREIGN KEY (`actividadId`) REFERENCES `ActividadKairos` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `HistorialActividadKairos_actorId_fkey` FOREIGN KEY (`actorId`) REFERENCES `Usuario` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `HistorialActividadKairos_reviewerId_fkey` FOREIGN KEY (`reviewerId`) REFERENCES `Usuario` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `HistorialActividadKairos_evidenceId_fkey` FOREIGN KEY (`evidenceId`) REFERENCES `EntregaEvidenciaKairos` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

ALTER TABLE Archivo ADD COLUMN propietarioId INT NULL, ADD INDEX Archivo_propietarioId_idx (propietarioId), ADD CONSTRAINT Archivo_propietarioId_fkey FOREIGN KEY (propietarioId) REFERENCES Usuario(id) ON DELETE SET NULL ON UPDATE CASCADE;
